function bubbleMove(mcname, mcx, mcy, frame)
{
   var _loc1_ = this;
   var _loc2_ = mcname;
   if(_loc1_._currentframe > frame)
   {
      _loc1_[_loc2_]._x += (mcx - _loc1_[_loc2_]._x) * 0.1;
      _loc1_[_loc2_]._y += (mcy - _loc1_[_loc2_]._y) * 0.1;
      _loc1_[_loc2_]._visible = true;
      _loc1_[_loc2_].play();
   }
   else
   {
      _loc1_[_loc2_]._visible = false;
   }
}

